import * as db from './store.js';
const styles=[['korean','韩系清新',[['cherry_blossom','樱花贴纸'],['hot_beverage','热饮贴纸']],['抹茶花枝',70,64]],['american','美式拼贴',[['sunflower','向日葵贴纸'],['camera_with_flash','相机贴纸']],['相机花束',70,64]],['vintage','复古旧物',[['old_key','旧钥匙贴纸'],['feather','羽毛贴纸']],['植物标本',50,75]],['minimal','极简留白',[['leaf_fluttering_in_wind','叶片贴纸'],['potted_plant','盆栽贴纸']],['枝叶陶瓶',50,75]],['editorial','杂志编辑',[['newspaper','报纸贴纸'],['pen','笔贴纸']],['鸢尾陶杯',50,75]],['film','胶片日记',[['clapper_board','场记板贴纸'],['camera','相机小贴纸']],['胶片相机',70,64]],['travel','旅行票据',[['compass','罗盘贴纸'],['ticket','票券贴纸']],['罗盘地图',70,58]],['cute','可爱插画',[['cat_face','猫咪贴纸'],['strawberry','草莓贴纸']],null],['mixed','混合媒材',[['artist_palette','调色盘贴纸'],['paintbrush','画笔贴纸']],null],['bullet','清单手帐',[['calendar','日历贴纸'],['pushpin','图钉贴纸']],null]];
const base=[['backing','纹样书写底纸','paper','background',115,152,'paper',1],['notecard','横向书写卡','paper','annotation',92,52,'paper',1],['ticket','可写票据','paper','support',72,46,'paper',1],['washi','纹样纸胶带','tape','connector',75,17,'washi',3],['special','风格构件','paper','support',60,52,'paper',1]];
const realism=[['barley-tea','麦茶杯纸贴','sticker','support',26,26,'die-cut photographic print',1],['cherry-sprig','樱花枝纸贴','sticker','support',26,26,'die-cut botanical print',1],['pressed-clover','压花三叶草纸贴','sticker','support',26,26,'die-cut pressed botanical print',1],['scallop-memo','波浪边手写卡','paper','annotation',60,52,'fibrous stationery paper',1],['notecard','棉纸横向记事卡','paper','annotation',92,52,'uncoated cotton paper',1],['backing','浅纹竖向书写底纸','paper','background',115,152,'fibrous writing paper',1],['label','棉纸空白标签','paper','annotation',70,37,'uncoated paper label',1],['ticket','撕线记事票','paper','support',72,37,'perforated paper ticket',1],['washi','点纹纤维纸胶带','tape','connector',60,20,'translucent washi paper',3],['paper','棉纸横线书写页','paper','background',160,210,'uncoated writing paper',1]];
const fixed=n=>`B7000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
export async function seedSwiftBundledMaterials(){if(await db.get('meta','swift-bundled-materials-current'))return;
 const existing=new Map((await db.all('assets')).map(a=>[a.id,a])),assets=[];
 for(const [index,[slug,style,web,original]] of styles.entries()){
  const pieces=[...base.map(([suffix,...rest])=>[`${slug}-extra-${suffix}.png`,...rest]),...web.map(([suffix,name])=>[`${slug}-extra-web-${suffix}.png`,name,'sticker','support',26,26,'printed sticker',1])];
  if(original)pieces.push([`${slug}-extra-original.png`,original[0],'sticker','focal',original[1],original[2],'illustrated cutout',1]);
  if(slug==='film')pieces.push(['film-extra-rain-window.png','雨窗夜景','photo','focal',68,90,'film print',1],['film-extra-red-path.png','红光林间','photo','support',68,90,'film print',1]);
  for(const [offset,[filename,name,kind,role,width,height,texture,quantity]] of pieces.entries())await add(fixed((index+1)*100+20+offset),style,name,filename,kind,role,width,height,texture,quantity,'built-in-style-expansion');
 }
 for(const [offset,[file,name,kind,role,width,height,texture,quantity]] of realism.entries())await add(fixed(180+offset),'韩系清新',name,`korean-realism-${file}.png`,kind,role,width,height,texture,quantity,'built-in-style-realism');
 async function add(id,style,name,filename,kind,role,width,height,texture,quantity,sourceIdentifier){if(existing.has(id))return;const blobId=id+'-image';assets.push({id,staticPath:`/style-expansion/${filename}`,title:`${style} · ${name}`,kind,role,tags:[style,name,sourceIdentifier==='built-in-style-realism'?'实体文具':'扩展素材'],styleTags:[style],materialTags:[texture],contentTags:[name],palette:[],texture,blobId,originalBlobId:blobId,physicalWidthMM:width,physicalHeightMM:height,dimensionSource:'manual',supply:{kind:kind==='tape'?'quantity':'single',quantity},reviewStatus:'ready',seriesID:fixed((style==='韩系清新'?1:styles.findIndex(x=>x[1]===style)+1)*100),createdAt:new Date(1750000000000).toISOString(),sourceIdentifier});}
 await db.transaction(['assets','meta'],tx=>{for(const a of assets)tx.objectStore('assets').put(a);tx.objectStore('meta').put({id:'swift-bundled-materials-current',createdAt:new Date().toISOString()});});}
